function fairTrade(alice: number[], bob: number[]): number[] {
  const sa = alice.reduce((s, v) => s + v, 0), sb = bob.reduce((s, v) => s + v, 0);
  const half = (sb - sa) / 2;
  const have = new Set(bob);
  for (const x of alice) if (have.has(x + half)) return [x, x + half];
  return [];
}

